<template>
  <div v-if="open" class="fixed inset-0 z-[80] grid place-items-center bg-black/40 p-3" @click.self="$emit('close')"><section role="dialog" aria-modal="true" aria-labelledby="link-title" class="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-xl border border-border bg-white p-5 shadow-xl sm:p-7"><header class="flex items-start justify-between gap-4"><div><h2 id="link-title" class="text-xl font-semibold">Link Creator channels</h2><p class="mt-1 text-sm text-muted-foreground">The Creator must consent before any channel access is granted.</p></div><button type="button" aria-label="Close" class="rounded p-2 hover:bg-muted focus-visible:outline focus-visible:outline-2" @click="$emit('close')">×</button></header>
    <div class="mt-6 grid gap-4 sm:grid-cols-2"><label class="grid gap-1.5 text-sm font-medium">Organization<select v-model="organizationId" class="h-10 rounded-md border border-input bg-background px-3" @change="loadMcns"><option value="">Choose Organization</option><option v-for="o in organizations" :key="o.id" :value="o.id">{{ o.brand_name || o.name }}</option></select></label><label class="grid gap-1.5 text-sm font-medium">MCN<select v-model="mcnId" class="h-10 rounded-md border border-input bg-background px-3" :disabled="!organizationId" @change="loadChannels"><option value="">Choose MCN</option><option v-for="m in mcns" :key="m.id" :value="m.id">{{ m.name }}</option></select></label></div>
    <fieldset class="mt-5"><legend class="text-sm font-medium">Channels in this MCN</legend><p v-if="!channels.length" class="mt-2 text-sm text-muted-foreground">Choose an MCN to view its channels.</p><div v-else class="mt-2 max-h-48 divide-y overflow-y-auto rounded-md border border-border"><label v-for="c in channels" :key="c.id" class="flex cursor-pointer items-center gap-3 p-3 text-sm hover:bg-muted/50"><input v-model="channelIds" type="checkbox" :value="c.id" class="accent-violet-600"><span>{{ c.title || c.channel_id }} <small class="text-muted-foreground">{{ c.channel_id }}</small></span></label></div></fieldset>
    <div class="mt-5 grid gap-4"><label class="grid gap-1.5 text-sm font-medium">Evidence reference<input v-model="evidence" required minlength="4" placeholder="Case or document reference" class="h-10 rounded-md border border-input bg-background px-3"></label><label class="grid gap-1.5 text-sm font-medium">Review notes<textarea v-model="reason" required minlength="8" rows="3" class="rounded-md border border-input bg-background p-3"></textarea></label></div>
    <p v-if="error" role="alert" class="mt-4 text-sm text-red-600">{{ error }}</p><footer class="mt-6 flex justify-end gap-3"><button class="rounded-md border border-border px-4 py-2 text-sm" @click="$emit('close')">Cancel</button><button class="rounded-md bg-primary px-4 py-2 text-sm font-medium text-primary-foreground disabled:opacity-50" :disabled="saving || !organizationId || !mcnId || !channelIds.length || evidence.length<4 || reason.length<8" @click="submit">{{ saving ? 'Sending…' : 'Send proposal' }}</button></footer>
  </section></div>
</template>
<script setup lang="ts">
const props=defineProps<{open:boolean;targetUserId:string;replaceRequestId?:string|null}>();const emit=defineEmits<{close:[];created:[]}>()
const {get,post}=useApi();const organizations=ref<any[]>([]),mcns=ref<any[]>([]),channels=ref<any[]>([]),organizationId=ref(''),mcnId=ref(''),channelIds=ref<string[]>([]),evidence=ref(''),reason=ref(''),saving=ref(false),error=ref('')
watch(()=>props.open,async value=>{if(!value)return;try{organizations.value=(await get('/api/v1/organizations',{params:{page:1,page_size:100}})).data.items||[]}catch{error.value='Organizations could not be loaded.'}})
const loadMcns=async()=>{mcnId.value='';channels.value=[];channelIds.value=[];try{mcns.value=(await get('/api/v1/mcns',{params:{organization_id:organizationId.value,page:1,page_size:100}})).data.items||[]}catch{error.value='MCNs could not be loaded.'}}
const loadChannels=async()=>{channelIds.value=[];try{channels.value=(await get('/api/v1/channels',{params:{mcn_id:mcnId.value,page:1,page_size:100}})).data.items||[]}catch{error.value='Channels could not be loaded.'}}
const submit=async()=>{if(saving.value)return;saving.value=true;error.value='';try{const replacement={target_user_id:props.targetUserId,organization_id:organizationId.value,mcn_id:mcnId.value,channel_ids:channelIds.value,reason:reason.value,evidence_reference:evidence.value,idempotency_key:crypto.randomUUID()};if(props.replaceRequestId)await post(`/api/v1/admin/creator-channel-link-requests/${props.replaceRequestId}/action`,{action:'replace',replacement});else await post('/api/v1/admin/creator-channel-link-requests',replacement);emit('created');emit('close')}catch(e:any){error.value=e.response?.data?.detail||'Proposal could not be saved. Review channel conflicts and try again.'}finally{saving.value=false}}
</script>
